LEGACY_OBSERVATION = '[\n  {\n    "source": "benchmark_dataset/Variant15/inputs/workstation_capacity.csv",\n    "values": {\n      "Workstation": "W1",\n      "Capacity": "15"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/workstation_capacity.csv",\n    "values": {\n      "Workstation": "W2",\n      "Capacity": "14"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/workstation_capacity.csv",\n    "values": {\n      "Workstation": "W3",\n      "Capacity": "16"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/workstation_capacity.csv",\n    "values": {\n      "Workstation": "W4",\n      "Capacity": "13"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_costs.csv",\n    "values": {\n      "Workstation": "W1",\n      "J1": "6",\n      "J2": "8",\n      "J3": "18",\n      "J4": "20",\n      "J5": "21",\n      "J6": "19",\n      "J7": "23",\n      "J8": "22",\n      "J9": "24"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_costs.csv",\n    "values": {\n      "Workstation": "W2",\n      "J1": "19",\n      "J2": "18",\n      "J3": "7",\n      "J4": "6",\n      "J5": "20",\n      "J6": "22",\n      "J7": "21",\n      "J8": "23",\n      "J9": "25"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_costs.csv",\n    "values": {\n      "Workstation": "W3",\n      "J1": "22",\n      "J2": "21",\n      "J3": "20",\n      "J4": "19",\n      "J5": "5",\n      "J6": "7",\n      "J7": "18",\n      "J8": "20",\n      "J9": "21"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_costs.csv",\n    "values": {\n      "Workstation": "W4",\n      "J1": "21",\n      "J2": "22",\n      "J3": "23",\n      "J4": "20",\n      "J5": "19",\n      "J6": "18",\n      "J7": "6",\n      "J8": "8",\n      "J9": "7"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_resources.csv",\n    "values": {\n      "Workstation": "W1",\n      "J1": "4",\n      "J2": "5",\n      "J3": "7",\n      "J4": "8",\n      "J5": "8",\n      "J6": "7",\n      "J7": "8",\n      "J8": "9",\n      "J9": "8"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_resources.csv",\n    "values": {\n      "Workstation": "W2",\n      "J1": "7",\n      "J2": "8",\n      "J3": "4",\n      "J4": "5",\n      "J5": "8",\n      "J6": "8",\n      "J7": "7",\n      "J8": "8",\n      "J9": "9"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_resources.csv",\n    "values": {\n      "Workstation": "W3",\n      "J1": "8",\n      "J2": "7",\n      "J3": "8",\n      "J4": "7",\n      "J5": "5",\n      "J6": "4",\n      "J7": "7",\n      "J8": "8",\n      "J9": "7"\n    }\n  },\n  {\n    "source": "benchmark_dataset/Variant15/inputs/assignment_resources.csv",\n    "values": {\n      "Workstation": "W4",\n      "J1": "8",\n      "J2": "8",\n      "J3": "9",\n      "J4": "8",\n      "J5": "7",\n      "J6": "7",\n      "J7": "4",\n      "J8": "5",\n      "J9": "4"\n    }\n  }\n]'
LEGACY_RECORDS = [{'source': 'benchmark_dataset/Variant15/inputs/workstation_capacity.csv', 'values': {'Workstation': 'W1', 'Capacity': '15'}}, {'source': 'benchmark_dataset/Variant15/inputs/workstation_capacity.csv', 'values': {'Workstation': 'W2', 'Capacity': '14'}}, {'source': 'benchmark_dataset/Variant15/inputs/workstation_capacity.csv', 'values': {'Workstation': 'W3', 'Capacity': '16'}}, {'source': 'benchmark_dataset/Variant15/inputs/workstation_capacity.csv', 'values': {'Workstation': 'W4', 'Capacity': '13'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_costs.csv', 'values': {'Workstation': 'W1', 'J1': '6', 'J2': '8', 'J3': '18', 'J4': '20', 'J5': '21', 'J6': '19', 'J7': '23', 'J8': '22', 'J9': '24'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_costs.csv', 'values': {'Workstation': 'W2', 'J1': '19', 'J2': '18', 'J3': '7', 'J4': '6', 'J5': '20', 'J6': '22', 'J7': '21', 'J8': '23', 'J9': '25'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_costs.csv', 'values': {'Workstation': 'W3', 'J1': '22', 'J2': '21', 'J3': '20', 'J4': '19', 'J5': '5', 'J6': '7', 'J7': '18', 'J8': '20', 'J9': '21'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_costs.csv', 'values': {'Workstation': 'W4', 'J1': '21', 'J2': '22', 'J3': '23', 'J4': '20', 'J5': '19', 'J6': '18', 'J7': '6', 'J8': '8', 'J9': '7'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_resources.csv', 'values': {'Workstation': 'W1', 'J1': '4', 'J2': '5', 'J3': '7', 'J4': '8', 'J5': '8', 'J6': '7', 'J7': '8', 'J8': '9', 'J9': '8'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_resources.csv', 'values': {'Workstation': 'W2', 'J1': '7', 'J2': '8', 'J3': '4', 'J4': '5', 'J5': '8', 'J6': '8', 'J7': '7', 'J8': '8', 'J9': '9'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_resources.csv', 'values': {'Workstation': 'W3', 'J1': '8', 'J2': '7', 'J3': '8', 'J4': '7', 'J5': '5', 'J6': '4', 'J7': '7', 'J8': '8', 'J9': '7'}}, {'source': 'benchmark_dataset/Variant15/inputs/assignment_resources.csv', 'values': {'Workstation': 'W4', 'J1': '8', 'J2': '8', 'J3': '9', 'J4': '8', 'J5': '7', 'J6': '7', 'J7': '4', 'J8': '5', 'J9': '4'}}]
import gurobipy as gp
from gurobipy import GRB
workstation_capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('workstation_capacity.csv')]
workstations = []
workstation_capacities = {}
for rec in workstation_capacity_records:
    ws = rec['values']['Workstation']
    cap = int(rec['values']['Capacity'])
    workstations.append(ws)
    workstation_capacities[ws] = cap
assignment_costs_records = [r for r in LEGACY_RECORDS if r['source'].endswith('assignment_costs.csv')]
jobs = []
assignment_costs = {}
for rec in assignment_costs_records:
    ws = rec['values']['Workstation']
    assignment_costs[ws] = {}
    for (k, v) in rec['values'].items():
        if k == 'Workstation':
            continue
        assignment_costs[ws][k] = int(v)
        if k not in jobs:
            jobs.append(k)
assignment_resources_records = [r for r in LEGACY_RECORDS if r['source'].endswith('assignment_resources.csv')]
assignment_resources = {}
for rec in assignment_resources_records:
    ws = rec['values']['Workstation']
    assignment_resources[ws] = {}
    for (k, v) in rec['values'].items():
        if k == 'Workstation':
            continue
        assignment_resources[ws][k] = int(v)
for ws in workstations:
    if ws not in assignment_costs or ws not in assignment_resources:
        raise ValueError(f'Missing cost or resource data for workstation {ws}')
    for j in jobs:
        if j not in assignment_costs[ws]:
            raise ValueError(f'Missing cost for workstation {ws}, job {j}')
        if j not in assignment_resources[ws]:
            raise ValueError(f'Missing resource for workstation {ws}, job {j}')
m = gp.Model('GeneralizedAssignment')
x_vars = m.addVars(workstations, jobs, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((assignment_costs[ws][j] * x_vars[ws, j] for ws in workstations for j in jobs)), GRB.MINIMIZE)
m.addConstrs((gp.quicksum((x_vars[ws, j] for ws in workstations)) == 1 for j in jobs), name='')
m.addConstrs((gp.quicksum((assignment_resources[ws][j] * x_vars[ws, j] for j in jobs)) <= workstation_capacities[ws] for ws in workstations), name='')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for v in m.getVars():
        print(f'{v.VarName}: {v.X}')
else:
    print(f'Solver status: {m.Status}')